# bash completion for pi (spec version 0.84.2)
# Generated by pi-completion. Do not edit by hand.
export PI_COMPLETION_VERSION="0.84.2"
_pi()
{
	local cur prev
	cur="${COMP_WORDS[COMP_CWORD]}"
	prev="${COMP_WORDS[COMP_CWORD-1]}"

	# Value completion for top-level flags.
	case "$prev" in
		--mode)
			COMPREPLY+=( $(compgen -W "text json rpc" -- "$cur") )
			return 0
			;;
		--session-dir)
			compopt -o dirnames 2>/dev/null
					COMPREPLY+=( $(compgen -d -- "$cur") )
			return 0
			;;
		--thinking)
			COMPREPLY+=( $(compgen -W "off minimal low medium high xhigh max" -- "$cur") )
			return 0
			;;
		--extension|-e)
			compopt -o filenames 2>/dev/null
					COMPREPLY+=( $(compgen -f -- "$cur") )
			return 0
			;;
		--skill)
			compopt -o filenames 2>/dev/null
					COMPREPLY+=( $(compgen -f -- "$cur") )
			return 0
			;;
		--prompt-template)
			compopt -o filenames 2>/dev/null
					COMPREPLY+=( $(compgen -f -- "$cur") )
			return 0
			;;
		--theme)
			compopt -o filenames 2>/dev/null
					COMPREPLY+=( $(compgen -f -- "$cur") )
			return 0
			;;
		--export)
			compopt -o filenames 2>/dev/null
					COMPREPLY+=( $(compgen -f -- "$cur") )
			return 0
			;;
		--tui-mode)
			COMPREPLY+=( $(compgen -W "regular fullscreen" -- "$cur") )
			return 0
			;;
		esac


	if [[ $COMP_CWORD -eq 1 ]]; then
		COMPREPLY+=( $(compgen -W "install remove uninstall update list config auth" -- "$cur") )
		COMPREPLY+=( $(compgen -W "--provider --model --api-key --system-prompt --append-system-prompt --mode --print -p --continue -c --resume -r --session --session-id --fork --session-dir --no-session --name -n --models --no-tools -nt --no-builtin-tools -nbt --tools -t --exclude-tools -xt --thinking --extension -e --no-extensions -ne --skill --no-skills -ns --prompt-template --no-prompt-templates -np --theme --use-theme --no-themes --no-context-files -nc --export --list-models --verbose --tui-mode --approve -a --no-approve -na --offline --help -h --version -v" -- "$cur") )
		return 0
	fi

	case "${COMP_WORDS[1]}" in
	install)
		# Install extension source and add to settings
		# positional: <source>

		COMPREPLY+=( $(compgen -W "--local -l --approve -a --no-approve -na --help -h" -- "$cur") )
		return 0
		;;

	remove|uninstall)
		# Remove extension source from settings
		# positional: <source>

		COMPREPLY+=( $(compgen -W "--local -l --approve -a --no-approve -na --help -h" -- "$cur") )
		return 0
		;;

	update)
		# Update pi, extensions, or model catalogs
		# positional: [source|self|pi]

		COMPREPLY+=( $(compgen -W "--self --extensions --models --all --extension --force --approve -a --no-approve -na --help -h" -- "$cur") )
		return 0
		;;

	list)
		# List installed extensions from settings

		COMPREPLY+=( $(compgen -W "--approve -a --no-approve -na --help -h" -- "$cur") )
		return 0
		;;

	config)
		# Open TUI to enable/disable package resources

		COMPREPLY+=( $(compgen -W "--local -l --approve -a --no-approve -na --help -h" -- "$cur") )
		return 0
		;;

	auth)
		# Print credentials for external clients
		if [[ $COMP_CWORD -eq 2 ]]; then
			COMPREPLY+=( $(compgen -W "check print-api-key print-bearer-token" -- "$cur") )
			return 0
		fi
		case "${COMP_WORDS[2]}" in
		check)

			COMPREPLY+=( $(compgen -W "--provider --model --json --credentials --no-refresh --help -h" -- "$cur") )
			return 0
			;;
		print-api-key)

			COMPREPLY+=( $(compgen -W "--provider --model --help -h" -- "$cur") )
			return 0
			;;
		print-bearer-token)

			COMPREPLY+=( $(compgen -W "--provider --model --min-expiry --help -h" -- "$cur") )
			return 0
			;;
		esac
		;;

	esac
}

complete -o bashdefault -o default -F _pi pi
